    const swirl = boss.d < 9 && boss.d > 6 ? 0.2 : 0;
    const brick = o.shots.some(s => !s.shootable && s.d < 3 && Math.abs(s.b) < 0.6);
    return { turn: clampU(boss.b * 3 + swirl), move: o.drop.f < 2 && mv > 0 ? 0 : mv, fire, jump: (wave || threat || brick) && o.ground };
  }

  // ladder: the lattice is only climbable facing west from the east; push in once aligned
  const lattice = g.kind === 'ladder' || (g.kind === 'ladder-approach' && g.d < 2.5);
  if (lattice) {
    const e = wrapA(Math.PI - o.yaw);
    return { turn: clampU(e * 3), move: Math.abs(e) < 0.5 ? 1 : 0, fire, jump: false };
  }

  // lift: stand still on it, it rises as long as you stand there
  if (g.kind === 'lift' && g.d < 1.2) return { turn: steerTo(g.b, 2), move: 0, fire, jump: threat };

  // stuck: no vertical progress for ~3 s, so hop and wander
  if (stuck) return { turn: Math.sin(m.n * 0.7), move: o.drop.f < 1.5 ? 0 : 0.2, fire, jump: true };

  const ramp = /stairs|spring|crane/.test(g.kind);
  const edge = o.drop.f < 1.5 && !ramp;
  // grab nearby juice when hurt
  const heal = o.hp < 60 ? o.items.find(i => i.k === 'juice' && i.d < 6) : undefined;
  const tb = heal ? heal.b : g.b;
  // spring: walk onto the pad and let it throw you; crane-step: hop across gaps
  const hop = threat || (g.kind === 'crane-step' && g.d < 1.5 && o.ground);
  const walk = edge ? 0 : Math.abs(tb) < 1.2 ? 0.2 : 0.05;
  return { turn: steerTo(tb, 2), move: walk, fire, jump: hop };
}

// special states first; ladders: face west and push in; lift: stand still; otherwise walk slowly toward the goal, firing heavily
function wrap(a) { return Math.atan2(Math.sin(a), Math.cos(a)); }
function clamp(v) { return Math.max(-1, Math.min(1, v)); }
function step(o, m) {
  m.n = (m.n || 0) + 1;
  if (o.carried) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.hang) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 2 === 0 };
  const g = o.goal;
  const near = o.foes.find(f => f.awake && f.d < 10);
  const fire = !!o.aim.hit || (!!near && m.n % 2 === 0);
  const slam = o.foes.some(f => f.st === 'slam' && f.d < 4);
  if (g.kind === 'ladder' || g.kind === 'ladder-approach') {
    const e = wrap(Math.PI - o.yaw);
    const ok = Math.abs(e) < 0.5;
    // far from the approach and not facing west: walk toward the approach point first
    if (g.kind === 'ladder-approach' && g.d > 1.5 && !ok) return { turn: steerTo(g.b, 2), move: Math.abs(g.b) < 1 ? 0.5 : 0, fire, jump: slam };
    return { turn: clamp(e * 3), move: ok ? (g.kind === 'ladder' ? 1 : 0.4) : 0, fire, jump: slam };
  }
  // lift: stand still once on it; spring: charge the pad at a firm pace
  if (g.kind === 'lift' && g.d < 1.2) return { turn: clamp(g.b * 2), move: 0, fire, jump: slam };
  const edge = o.drop.f < 1.5 && g.kind !== 'spring';
  const move = Math.abs(g.b) < 1 && !edge ? (g.kind === 'spring' ? 0.8 : 0.35) : 0;
  return { turn: clamp(g.b * 2), move, fire, jump: slam };
}

// special states first; ladders: face west and push in; lift: stand still; otherwise walk slowly toward the goal, firing heavily
function wrap(a) { return Math.atan2(Math.sin(a), Math.cos(a)); }
function clamp(v) { return Math.max(-1, Math.min(1, v)); }
function step(o, m) {
  m.n = (m.n || 0) + 1;
  if (o.carried) return { turn: 0, move: 0, fire: false, jump: true };
  if (o.hang) return { turn: 0, move: 0, fire: false, jump: m.n % 2 === 0 };
  if (o.rider) return { turn: m.n % 4 < 2 ? -1 : 1, move: 0, fire: false, jump: m.n % 3 === 0 };
  const g = o.goal;
  const near = o.foes.find(f => f.awake && f.d < 10);
  const fire = (!!o.aim.hit || !!near) && m.n % 3 === 0;
  m.c = Math.abs(o.y - (m.py === undefined ? o.y : m.py)) < 0.05 ? (m.c || 0) + 1 : 0;
  m.py = o.y;
  if (m.c > 40 && g.kind !== 'ladder' && g.kind !== 'lift') {
    if (m.c > 52) m.c = 0;
    return { turn: Math.sin(m.n * 0.7), move: o.drop.f < 1.5 ? 0 : 0.5, fire, jump: true };
  }
  const hold = o.foes.some(f => f.awake && f.band && f.d < 7);
  const slam = o.foes.some(f => f.st === 'slam' && f.d < 4);
  if (g.kind === 'ladder' || g.kind === 'ladder-approach') {
    const e = wrap(Math.PI - o.yaw);
    const ok = Math.abs(e) < 0.5;
    return { turn: clamp(e * 3), move: ok ? (g.kind === 'ladder' ? 1 : 0.4) : 0, fire, jump: slam };
  }
  if (g.kind === 'lift' && g.d < 1.2) return { turn: clamp(g.b * 2), move: 0, fire, jump: slam };
  // steady walk toward the goal; stairs treads are not drops, so only real edges stop us
  const edge = o.drop.f < 1.5 && g.kind !== 'spring' && g.kind !== 'stairs' && g.kind !== 'stairs-approach';
  const move = Math.abs(g.b) < 1.2 && !edge && !hold ? (Math.abs(g.b) < 0.5 ? 0.25 : 0.1) : 0;
  // at a drop, turn toward the side with more ground
  const turn = edge ? (o.drop.r > o.drop.l ? 0.6 : -0.6) : clamp(g.b * 2);
  return { turn, move, fire, jump: slam };
}
